def question(grade, topic, number, prompt, options, correct, explanation):
    return {'id': f'learn-{grade}-{topic}-{number}', 'grade': grade, 'topic': topic,
            'area': TOPICS[topic]['name'], 'prompt': prompt, 'options': options,
            'correct': correct, 'explanation': explanation}


